  box-shadow: 0 12px 34px rgba(0,0,0,0.35);
  opacity: 0;
  transform: translateY(3px);
  transition: opacity 130ms ease, transform 130ms ease;
  max-width: 320px;
  font-size: 12px;
  line-height: 1.35;
