  text-align: left;
  padding: 10px 10px;
  color: rgba(231, 238, 252, 0.92);
}

.dataTable td {
  border-bottom: 1px solid rgba(231, 238, 252, 0.08);
  padding: 9px 10px;
  font-size: 12px;
  color: rgba(231, 238, 252, 0.9);
